use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        // Length is preserved
        result.len() == a.len(),
        // If the vector has 0 or 1 element, result is identical to the input
        a.len() <= 1 ==> result@ == a@,
        // If the vector has 2+ elements, result is the same as `a` except
        // the first and last elements are swapped.
        a.len() > 1 ==> (
            result[0] == a[a.len() - 1]
            && result[a.len() - 1] == a[0]
            && forall|i: int|
                0 <= i < a.len() && i != 0 && i != a.len() - 1
                ==> result[i] == a[i]
        ),
{
    let n = a.len();
    if n <= 1 {
        return a.clone();
    }

    let mut result = a.clone();
    result.swap(0, n - 1);
    result
}

} // verus!